def _cutoff_report_facts(cutoff_dt: str) -> tuple[list[str], list[str]]:
    """cutoff 日日报原文。取【今日结果】最全的一份，不读空的「已完成」占位。"""
    best_done: list[str] = []
    best_next: list[str] = []
    for path in _report_paths(cutoff_dt):
        if not path.is_file():
            continue
        try:
            raw = path.read_text(encoding='utf-8')
        except OSError:
            continue
        done = _section_lines(raw, '今日结果')
        nxt = _section_lines(raw, '明日动作')
        if len(done) > len(best_done):
            best_done = done
        if len(nxt) > len(best_next):
            best_next = nxt
    return best_done, best_next


def _title_keys(title: str) -> list[str]:
    keys: list[str] = []
    for pat, aliases in (
        (r'渠道', ['渠道']),
        (r'指标', ['指标']),
        (r'设备|指纹|uid_map', ['设备标签', '指纹', 'uid_map']),
        (r'归因', ['归因']),
        (r'漏斗', ['漏斗']),
        (r'告警', ['告警']),
        (r'页面|停留|访问', ['页面访问', '停留']),
    ):
        if re.search(pat, title):
            keys.extend(aliases)
    stop = {'汇总', '报表', '维护', '任务', '推广', '升级', '值班', '性能', '试验', '开发', '相关'}
    for token in re.findall(r'[\u4e00-\u9fffA-Za-z0-9_]{2,}', title):
        if token not in stop and token not in keys:
            keys.append(token)
    return keys


def _facts_for_title(title: str, lines: list[str]) -> list[str]:
    keys = _title_keys(title)
    if not keys:
        return []
    return [line for line in lines if any(k in line for k in keys)][:3]


_TEMPLATE_NOTE_RE = re.compile(r'未查到探针数字|不套模板|任务板仅挂账')


def _apply_report_facts(
    title: str,
    status: str,
    note: str,
    done: list[str],
    nxt: list[str],
    cutoff_dt: str,
) -> tuple[str, str]:
    """进展以日报原句为主。有完成句就写已完成，禁止任务板状态冒充进度。"""
    done_hits = _facts_for_title(title, done)
    next_hits = _facts_for_title(title, nxt)
    kept = _TEMPLATE_NOTE_RE.sub('', note or '').strip('；; ')
    parts: list[str] = []
    parts.extend(done_hits)
    if kept:
        parts.append(kept)
    if next_hits and not done_hits:
        parts.append(next_hits[0])
    text = '；'.join(p for p in parts if p)
    blob = text
    if done_hits and any('已完成' in line for line in done_hits):
        status = '已完成'
    elif any(k in blob for k in ('仍停', 'HOLD', '勿并')):
        status = '仍停'
    elif not done_hits and any(k in blob for k in ('等审核', '待运维')):
        status = '等审核'
    elif not text:
        status = '无当日记录'
        text = f'截至 {cutoff_dt} 日报没有这项的完成记录'
    elif not status:
        status = '有记录'
    return status, text

